const o = require('ospec');
const { success, error } = require('../src/helper');

const { romanize } = require('../src/romanize');

const assert = (kana, romaji) => {
  o(romanize(kana)).deepEquals(success(romaji));
};

o.spec('romanize', () => {
  o('romanizes vowels', () => {
    assert('あ', 'a');
    assert('い', 'i');
    assert('う', 'u');
    assert('え', 'e');
    assert('お', 'o');
  });

  o('romanizes k- syllables', () => {
    assert('かきくけこ', 'kakikukeko');
  });

  o('romanizes s- syllables', () => {
    assert('さしすせそ', 'sasisuseso');
  });

  o('romanizes t- syllables', () => {
    assert('たちつてと', 'tatituteto');
  });

  o('romanizes n- syllables', () => {
    assert('なにぬねの', 'naninuneno');
  });

  o('romanizes h- syllables', () => {
    assert('はひふへほ', 'hahihuheho');
  });

  o('romanizes m- syllables', () => {
    assert('まみむめも', 'mamimumemo');
  });

  o('romanizes r- syllables', () => {
    assert('らりるれろ', 'rarirurero');
  });

  o('romanizes g- syllables', () => {
    assert('がぎぐげご', 'gagigugego');
  });

  o('romanizes z- syllables', () => {
    assert('ざじずぜぞ', 'zazizuzezo');
  });

  o('romanizes d- syllables', () => {
    assert('だぢづでど', 'dadidudedo');
  });

  o('romanizes b- syllables', () => {
    assert('ばびぶべぼ', 'babibubebo');
  });

  o('romanizes p- syllables', () => {
    assert('ぱぴぷぺぽ', 'papipupepo');
  });

  o('romanizes moraic n', () => {
    assert('たん', 'tan');
    assert('たんい', "tan'i");
    assert('おんな', 'onna');
    assert('こんや', "kon'ya");
    assert('こにゃ', 'konya');
  });

  o('romanizes w- syllables', () => {
    assert('わを', 'wawo');
  });

  o('romanizes obsolete w- syllables', () => {
    assert('ゐゑ', 'wiwe');
  });

  o('romanizes y- syllables', () => {
    assert('やゆよ', 'yayuyo');
  });

  o('romanizes geminate sounds', () => {
    assert('けっか', 'kekka');
    assert('さっさと', 'sassato');
    assert('ずっと', 'zutto');
    assert('きっぷ', 'kippu');
    assert('ざっし', 'zassi');
    assert('こっち', 'kotti');
    assert('まっちゃ', 'mattya');
    assert('みっつ', 'mittu');
    assert('みっ', "mi'");
  });

  o('romanizes palatalized syllables', () => {
    assert('きゃきゅきょ', 'kyakyukyo');
    assert('しゃしゅしょ', 'syasyusyo');
    assert('ちゃちゅちょ', 'tyatyutyo');
    assert('にゃにゅにょ', 'nyanyunyo');
    assert('ひゃひゅひょ', 'hyahyuhyo');
    assert('みゃみゅみょ', 'myamyumyo');
    assert('りゃりゅりょ', 'ryaryuryo');
    assert('ぎゃぎゅぎょ', 'gyagyugyo');
    assert('じゃじゅじょ', 'zyazyuzyo');
    assert('ぢゃぢゅぢょ', 'dyadyudyo');
    assert('びゃびゅびょ', 'byabyubyo');
    assert('ぴゃぴゅぴょ', 'pyapyupyo');
  });

  o('romanizes long a vowel sounds', () => {
    assert('おばあさん', 'obaasan');
    assert('じゃあく', 'zyaaku');
  });

  o('romanizes long i vowel sounds', () => {
    assert('おにいさん', 'oniisan');
    assert('おいしい', 'oisii');
    assert('はいいろ', 'haiiro');
  });

  o('romanizes long u vowel sounds', () => {
    assert('くう', 'kuu');
    assert('みずうみ', 'mizuumi');
    assert('すうがく', 'suugaku');
  });

  o('romanizes long e vowel sounds', () => {
    assert('ぬれえん', 'nureen');
    assert('おねえさん', 'oneesan');
  });

  o('romanizes long o vowel sounds', () => {
    assert('こおどり', 'koodori');
    assert('こおり', 'koori');
  });

  o('romanizes o + u', () => {
    assert('おう', 'ou');
    assert('こうま', 'kouma');
    assert('がっこう', 'gakkou');
    assert('きんようび', "kin'youbi");
  });

  o('romanizes e + i', () => {
    assert('がくせい', 'gakusei');
    assert('まねいて', 'maneite');
  });

  o('romanizes other vowel combinations', () => {
    assert('かるい', 'karui');
    assert('うぐいす', 'uguisu');
    assert('おい', 'oi');
  });

  o('romanizes one to one katakana', () => {
    assert('アイウエオ', 'aiueo');
    assert('カキクケコ', 'kakikukeko');
    assert('サシスセソ', 'sasisuseso');
    assert('タチツテト', 'tatituteto');
    assert('ナニヌネノ', 'naninuneno');
    assert('ハヒフヘホ', 'hahihuheho');
    assert('マミムメモ', 'mamimumemo');
    assert('ラリルレロ', 'rarirurero');
    assert('ガギグゲゴ', 'gagigugego');
    assert('ザジズゼゾ', 'zazizuzezo');
    assert('ダヂヅデド', 'dadidudedo');
    assert('バビブベボ', 'babibubebo');
    assert('パピプペポ', 'papipupepo');
    assert('ヤユヨ', 'yayuyo');
    assert('ワヰヱヲ', 'wawiwewo');
    assert('ン', 'n');
    assert('ニャニュニョ', 'nyanyunyo');
    assert('メッチャ', 'mettya');
  });

  o('a non-kana string returns an error status by default', () => {
    o(romanize('a')).deepEquals(error('Error at a'));
    o(romanize('けa')).deepEquals(error('Error at a'));
  });

  o('can configure to merge long vowel sounds', () => {
    const config = {
      mergeLongVowels: true,
    };

    const assert = (kana, romaji) => {
      o(romanize(kana, config)).deepEquals(success(romaji));
    };

    assert('おばあさん', 'obāsan');
    assert('おにいさん', 'onīsan');
    assert('すうがく', 'sūgaku');
    assert('おねえさん', 'onēsan');
    assert('こおり', 'kōri');
    assert('がっこう', 'gakkō');
    assert('きんようび', "kin'yōbi");
    assert('がくせい', 'gakusei');
    assert('まねいて', 'maneite');
    assert('そうおん', 'sōon');
  });

  o('romanizes punctuation', () => {
    assert('－な', '-na');
    assert('。', '.');
    assert('、', ',');
    assert('？', '?');
    assert('！', '!');
    assert('：', ':');
    assert('〜', '~');
    assert('　', ' ');
    assert('『', '"');
    assert('』', '"');
    assert('〝', '"');
    assert('〟', '"');
    assert('「', "'");
    assert('」', "'");
    assert('・', '-');
    assert('…', '...');
    assert('｛', '{');
    assert('｝', '}');
    assert('（', '(');
    assert('）', ')');
    assert('［', '[');
    assert('］', ']');
    assert('【', '"');
    assert('】', '"');
  });

  o('can configure not to fail on non-kana strings', () => {
    const config = {
      nonKanaAllowed: true,
    };
    o(romanize('.なa', config)).deepEquals(success('.naa'));
    o(romanize('.さっa', config)).deepEquals(success(".sa'a"));
  });
});
